        if any(i.attrs.get('width')!='2656' or i.attrs.get('height')!='1600' or not i.attrs.get('alt') for i in imgs):errors.append('image dimensions/alt')
        if '0007.cervical-nerve-mechanism' in s:errors.append('rejected illustration still present')
        schemas=[n.text() for n in d.all('script') if n.attrs.get('type')=='application/ld+json']
        if len(schemas)!=1:errors.append('schema count')
        try:
            graph=json.loads(schemas[0])['@graph'];wp=next(n for n in graph if n.get('@type')=='MedicalWebPage');faq=next(n for n in graph if n.get('@type')=='FAQPage')['mainEntity']
            for entity in graph:
                if entity.get('procedureType')=='TherapeuticProcedure':errors.append('invalid procedureType enumeration')
                if any(x in ('TraditionalChineseMedicine','Acupuncture') for x in entity.get('medicalSpecialty',[])):errors.append('invalid medicalSpecialty enumeration')
            if wp.get('url')!=url or wp.get('inLanguage')!=lang:errors.append('schema locale')
            if wp['name']!=d.all('h1')[0].text():errors.append('schema heading')
            if len(faq)!=3:errors.append('faq count')
            visible=norm(d.all('main')[0].text())
            for q in faq:
                if norm(q['name']) not in visible or norm(q['acceptedAnswer']['text']) not in visible:errors.append('FAQ not in visible main')
        except (ValueError,KeyError,StopIteration,IndexError) as exc: errors.append('schema '+str(exc))
        if re.search(r'reviewedBy|lastReviewed',s):errors.append('unauthorized new physician attestation')
        for bad in ('10.30581/jkcmm.2018.13.2.11','safe.*prior to surgery','physically securing space','원인은 머리가 아닌','365 Days','365일','365天','대흉두신경'):
            if re.search(bad,s):errors.append('rejected claim '+bad)
        required={'ko':['수원','바디올','근막이완 추나','SART','같은 동작','119','아나필락시스'],'en':['Suwon','Bodyall','myofascial-release Chuna','SART','same movement','119','anaphylaxis'],'zh-Hans':['水原','Bodyall','筋膜放松推拿','SART','同一动作','119','过敏性休克']}[lang]
        for word in required:
            if word not in s:errors.append('missing topic concept '+word)
        for i in range(1,7):
            if f'ref-{i}' not in ids or not any(a.attrs.get('href')==f'#ref-{i}' for a in d.all('a')):errors.append('reference unused/missing '+str(i))
        reports.append({'path':rel,'sha256':digest(s),'errors':errors,'images':len(imgs),'full_html_parsed':True})
    return {'stage':'STATIC_ONLY','release_permitted':False,'reports':reports,'errors':sum(len(r['errors']) for r in reports)}

def release_errors(receipt, hashes):
    errors=[]
    if receipt.get('decision')!='PASS':errors.append('editor decision is not PASS')
    if receipt.get('unresolved_defects')!=[]:errors.append('unresolved defects or absent defect list')
    if receipt.get('exact_candidate_sha256')!=hashes:errors.append('missing/stale exact-candidate review')
    for key in ('complete_html_read','medical_claims_reviewed','clinic_provenance_reviewed','translations_aligned','recommendation_reason_recorded','approval_scope_preserved','static_checks_passed'):
        if receipt.get(key) is not True:errors.append('missing '+key)
    visual=receipt.get('render_review',{})
    for rel in hashes:
        views=visual.get(rel,{})
        for mode in ('desktop','narrow'):
            result=views.get(mode,{})
            if result.get('inspected') is not True or result.get('candidate_sha256')!=hashes[rel] or not result.get('evidence'):
                errors.append(rel+': missing exact '+mode+' render evidence')
    return errors

def self_test(hashes):
    r={'decision':'PASS','unresolved_defects':[],'exact_candidate_sha256':hashes.copy(),'render_review':{}}
    for key in ('complete_html_read','medical_claims_reviewed','clinic_provenance_reviewed','translations_aligned','recommendation_reason_recorded','approval_scope_preserved','static_checks_passed'):r[key]=True
    for rel,h in hashes.items():
        r['render_review'][rel]={mode:{'inspected':True,'candidate_sha256':h,'evidence':'SYNTHETIC TEST FIXTURE ONLY'} for mode in ('desktop','narrow')}
    assert not release_errors(r,hashes)
    bad=copy.deepcopy(r);bad['exact_candidate_sha256'][next(iter(hashes))]='stale';assert release_errors(bad,hashes)
    bad=copy.deepcopy(r);bad['render_review']={};assert release_errors(bad,hashes)
    bad=copy.deepcopy(r);bad['unresolved_defects']=['factual error'];assert release_errors(bad,hashes)
    bad=copy.deepcopy(r);bad['translations_aligned']=False;assert release_errors(bad,hashes)
    assert release_errors({},hashes)
    return 'PASS: synthetic positive + stale hash, missing renders, open defect, incomplete translation, absent receipt all blocked'

if __name__=='__main__':
    result=preflight();hashes={r['path']:r['sha256'] for r in result['reports']}
    if '--self-test' in sys.argv:result['gate_self_test']=self_test(hashes)
